  // The trailing timestamp is the stable handle we use to fork at this turn.
  const messageId = useMessage((message) => message.id);
  const messageText = useMessage((message) =>
    (message.content as Array<{ type: string; text?: string }>)
      .filter((part) => part.type === "text")
      .map((part) => part.text ?? "")
      .join("\n\n"),
  );
  const copyText = stripOpenUIPrograms(
    stripQuizTags(
      stripGeneratedImageTags(
        stripQuestionTags(stripGoalTags(stripArtifactLinks(messageText))),
      ),
    ),
  ).trim();
  const handleFork = () => {
    const ts = Number(messageId.slice(messageId.lastIndexOf("-") + 1));
    onFork?.(Number.isFinite(ts) ? ts : undefined);
  };
  const [retrying, setRetrying] = useState(false);

  const handleFeedbackClick = (type: "up" | "down") => {
    setFeedbackType(type);
    setFeedbackModalOpen(true);
  };

  const handleFeedbackSubmit = (type: "up" | "down", comment: string) => {
    setFeedback(type);
    setFeedbackModalOpen(false);
    try {
      window.dispatchEvent(
        new CustomEvent("keating:message-feedback", {
          detail: {
            type,
            comment,
            messageId,
            messageText: copyText,
            messageCreatedAt:
              Number(messageId.slice(messageId.lastIndexOf("-") + 1)) ||
              undefined,
          },
        }),
      );
    } catch {
      /* noop */
    }
  };

  const handleAuthRetry = async () => {
    if (!authError) return;
    setRetrying(true);
    try {
      await onAuthError(authError.provider);
    } finally {
      setRetrying(false);
    }
  };

  if (isPrefillStatus) {
    return <KeatingThinkingIndicator status={messageText} />;
  }

  return (
    <>
      <MessagePrimitive.Root
        className={css({
          marginInline: "auto",
          marginBottom: "1rem",
          display: "flex",
          width: "100%",
          maxWidth: "56rem",
          justifyContent: "flex-start",
          _hover: { "& [data-fork-action]": { opacity: 1 } },
        })}
      >
        <div
          className={css({
            display: "flex",
            width: "100%",
            gap: 0,
            paddingInline: 0,
            fontSize: "0.875rem",
            color: "var(--foreground)",
            sm: { gap: "0.75rem", paddingInline: "0.25rem" },
          })}
        >
          <div
            className={cx(
              "chat-avatar",
              css({
                display: "none",
                marginTop: "0.125rem",
                sm: { display: "flex" },
              }),
            )}
          >
            <img
              className="keating-mascot-image"
              src="/brand/mascot-head-v2.png"
              alt="Keating"
            />
          </div>
          <div className={css({ minWidth: 0, flex: 1, lineHeight: "1.5rem" })}>
            <div className="msg-meta">
              <b>KEATING</b>
            </div>
            <div className={cx("keating-bubble", foregroundTextClass)}>
              <MessagePrimitive.Content components={components} />
              {authError && (
                <div
                  className={css({
                    marginBlock: "0.5rem",
                    borderRadius: "0.5rem",
                    border:
                      "1px solid color-mix(in srgb, var(--destructive) 50%, transparent)",
                    backgroundColor:
                      "color-mix(in srgb, var(--destructive) 10%, transparent)",
                    padding: "0.75rem",
                    fontSize: "0.875rem",
                  })}
                >
                  <div
                    className={css({
                      display: "flex",
                      alignItems: "flex-start",
                      gap: "0.5rem",
                    })}
                  >
                    <KeyRound
                      size={16}
                      className={css({
                        marginTop: "0.125rem",
                        flexShrink: 0,
                        color: "var(--destructive)",
                      })}
                    />
                    <div className={css({ minWidth: 0, flex: 1 })}>
                      <p
                        className={css({
                          marginBottom: "0.25rem",
                          fontWeight: 500,
                          color: "var(--destructive)",
                        })}
                      >
                        Authentication failed
                      </p>
                      <p
                        className={css({
                          marginBottom: "0.5rem",
                          fontSize: "0.75rem",
                          color: "var(--muted-foreground)",
                        })}
                      >
                        {llmFailure?.recovery ??
                          "Re-enter the provider credentials, then Keating can retry the same turn."}
                      </p>
                      <button
                        type="button"
                        onClick={handleAuthRetry}
                        disabled={retrying}
                        className={cx(
                          srInteractiveClass,
                          css({
                            display: "inline-flex",
                            alignItems: "center",
                            gap: "0.375rem",
                            borderRadius: "0.375rem",
                            backgroundColor: "var(--primary)",
                            paddingInline: "0.75rem",
                            paddingBlock: "0.375rem",
                            fontSize: "0.75rem",
                            fontWeight: 500,
                            color: "var(--primary-foreground)",
                            _hover: {
                              backgroundColor:
                                "color-mix(in srgb, var(--primary) 90%, transparent)",
                            },
                            _disabled: { opacity: 0.5 },
                          }),
                        )}
                      >
                        {retrying ? (
                          <Spinner size={12} />
                        ) : (
                          <KeyRound size={12} />
                        )}
                        Re-enter API key
                      </button>
                      <a
                        href={tutorialApiKeyHref(authError.provider)}
                        onClick={(event) =>
                          handleTutorialLinkClick(
                            event.nativeEvent,
                            tutorialApiKeyHref(authError.provider),
                          )
                        }
                        className={css({
                          marginLeft: "0.5rem",
                          display: "inline-flex",
                          alignItems: "center",
                          fontSize: "0.75rem",
                          color: "var(--primary)",
                          textDecoration: "underline",
                          textUnderlineOffset: "2px",
                        })}
                      >
                        Need a key?
                      </a>
                    </div>
                  </div>
                </div>
              )}
            </div>
            {llmFailure && canRetry && onRetry && (
              <FailedResponseRecovery
                recovery={llmFailure.recovery}
                onRetry={onRetry}
              />
            )}
            {llmFailure && retryAttempts && retryAttempts > 1 && (
              <p
                className={css({
                  marginTop: "0.5rem",
                  fontSize: "0.75rem",
                  color: "var(--muted-foreground)",
                })}
                role="status"
              >
                {retryExhausted
                  ? `Automatic recovery stopped after ${retryAttempts} attempts.`
                  : `Keating made ${retryAttempts} recovery attempts before preserving this error.`}
              </p>
            )}
            <div
              className={css({
                marginTop: "0.5rem",
                display: "flex",
                alignItems: "center",
                gap: "0.25rem",
              })}
            >
              {copyText && (
                <CopyButton
                  variant="ghost"
                  text={copyText}
                  label="Copy message"
                />
              )}
              {llmFailure &&
                llmFailure.category !== "aborted" &&
                onModelSelect && (
                  <button
                    type="button"
                    className={cx(
                      messageActionButtonClass,
                      css({
                        width: "auto",
                        gap: "0.375rem",
                        paddingInline: "0.5rem",
                      }),
                    )}
                    onClick={onModelSelect}
                    title="Choose a different model"
                  >
                    <Server size={13} />
                    <span>Choose model</span>
                  </button>
                )}
              <button
                type="button"
                className={cx(
                  messageActionButtonClass,
                  feedback === "up"
                    ? css({
                        backgroundColor:
                          "color-mix(in srgb, var(--primary) 20%, transparent)",
                        color: "var(--primary)",
                      })
                    : "",
                )}
                title="Helpful"
                onClick={() => handleFeedbackClick("up")}
                aria-pressed={feedback === "up"}
              >
                <ThumbsUp size={13} />
              </button>
              <button
                type="button"
                className={cx(
                  messageActionButtonClass,
                  feedback === "down"
                    ? css({
                        backgroundColor:
                          "color-mix(in srgb, var(--destructive) 20%, transparent)",
                        color: "var(--destructive)",
                      })
                    : "",
                )}
                title="Not helpful"
                onClick={() => handleFeedbackClick("down")}
                aria-pressed={feedback === "down"}
              >
                <ThumbsDown size={13} />
              </button>
              {onFork && (
                <button
                  type="button"
                  data-fork-action
                  className={cx(
                    messageActionButtonClass,
                    css({ opacity: 0, _focus: { opacity: 1 } }),
                  )}
                  title="Fork session from here"
                  onClick={handleFork}
                  aria-label="Fork session from here"
                >
                  <CopyPlus size={13} />
                </button>
              )}
            </div>
          </div>
        </div>
      </MessagePrimitive.Root>
      <FeedbackModal
        open={feedbackModalOpen}
        type={feedbackType}
        onClose={() => setFeedbackModalOpen(false)}
        onSubmit={handleFeedbackSubmit}
      />
    </>
  );
}

function KeatingThinkingIndicator({ status }: { status: string }) {
  return (
    <div
      role="status"
      aria-live="polite"
      className={css({
        marginInline: "auto",
        marginBottom: "1rem",
        display: "flex",
        width: "100%",
        maxWidth: "56rem",
        alignItems: "center",
        gap: "0.75rem",
        color: "var(--muted-foreground)",
      })}
    >
      <div
        className={cx(
          "keating-thinking-mascot",
          css({
            display: "flex",
            height: "2.5rem",
            width: "2.5rem",
            flexShrink: 0,
            alignItems: "center",
            justifyContent: "center",
            borderRadius: "0.5rem",
            border: "1px solid var(--border)",
            backgroundColor: "var(--card)",
          }),
        )}
      >
        <img
          src="/brand/mascot-head-v2.png"
          alt=""
          className={`keating-mascot-image ${css({ width: "2.125rem", height: "auto" })}`}
        />
      </div>
      <div className={css({ minWidth: 0 })}>
        <div
          className={css({
            display: "flex",
            alignItems: "center",
            gap: "0.25rem",
            fontSize: "0.75rem",
            fontWeight: 600,
            color: "var(--foreground)",
          })}
        >
          Keating is thinking
          <span
            aria-hidden="true"
            className={css({ display: "inline-flex", gap: "0.1875rem" })}
          >
            {[0, 1, 2].map((index) => (
              <span
                key={index}
                className="keating-thinking-dot"
                style={{ animationDelay: `${index * 140}ms` }}
              />
            ))}
          </span>
        </div>
        <p
          className={css({
            marginTop: "0.125rem",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
            fontSize: "11px",
          })}
        >
          {status}
        </p>
      </div>
    </div>
  );
}

export const AssistantChatPanel = forwardRef<
  ChatPanelHandle,
  AssistantChatPanelProps
>(
  (
    {
      className,
      speechEnabled = false,
      responseComparison,
      initialPrompts,
      emptyStateTitle,
      emptyStateDescription,
      pendingPrompt,
    },
    ref,
  ) => {
    const [agent, setAgentState] = useState<Agent | null>(null);
    const [callbacks, setCallbacks] = useState<ChatPanelSetupCallbacks>({});
    const [version, setVersion] = useState(0);

    const refresh = useCallback(() => setVersion((current) => current + 1), []);

    useImperativeHandle(
      ref,
      () => ({
        async setAgent(nextAgent, nextCallbacks = {}) {
          setAgentState(nextAgent);
          setCallbacks(nextCallbacks);
          refresh();
        },
      }),
      [refresh],
    );

    return (
      <div className={className}>
        <AgentSubscription agent={agent} onChange={refresh} />
        <AssistantThread
          agent={agent}
          callbacks={callbacks}
          version={version}
          speechEnabled={speechEnabled}
          responseComparison={responseComparison}
          initialPrompts={initialPrompts}
          emptyStateTitle={emptyStateTitle}
          emptyStateDescription={emptyStateDescription}
          pendingPrompt={pendingPrompt}
        />
      </div>
    );
  },
);

AssistantChatPanel.displayName = "AssistantChatPanel";

// Test-only export for parser regressions around malformed reasoning tags from
// OpenAI-compatible providers.
export const __test_assistantTextParts = assistantTextParts;
export const __test_parseInteractiveSegments = parseInteractiveSegments;
export const __test_interactiveTagPattern = interactiveTagPattern;

function AgentSubscription({
  agent,
  onChange,
}: {
  agent: Agent | null;
  onChange: () => void;
}) {
  useEffect(() => {
    if (!agent) return undefined;
    const unsubscribe = agent.subscribe(() => onChange());
    onChange();
    return unsubscribe;
  }, [agent, onChange]);
  return null;
}

